/// <summary>
/// Finds a record
/// </summary>
/// <param name = "_inventTable">_inventTable</param>
/// <param name = "_update">true or false</param>
/// <returns>Record</returns>
static public NDXMultipleS_Sales find(InventTable _inventTable, boolean _update = false)
{
    NDXMultipleS_Sales lNDXMultipleS_Sales;

    if(_inventTable)
    {
        lNDXMultipleS_Sales.selectForUpdate(_update);

        select lNDXMultipleS_Sales
            where lNDXMultipleS_Sales.RefRecId_InventTable == _inventTable.RecId;
    }

    return lNDXMultipleS_Sales;
}

/// <summary>
/// Checks if a check is available
/// </summary>
/// <param name = "_inventTable">_inventTable</param>
/// <returns>true or false</returns>
static public boolean hasValidityCheck(InventTable _inventTable)
{
    return NDXMultipleS_Sales::find(_inventTable).RecId > 0;
}

/// <summary>
/// Returns all validation sales Ids as string
/// </summary>
/// <param name = "_itemRecId">_itemRecId</param>
/// <returns>String of sale ids</returns>
static str Range2String(RecId _itemRecId)
{
    #define.Comma(' ,')

    NDXMultipleS_Sales     nDX_MultipleS_Sales;
    SalesTable lSalesTable;
    str range2String;
    boolean                 lFirst = true;
    ;
    while select nDX_MultipleS_Sales
        where nDX_MultipleS_Sales.RefRecId_InventTable == _itemRecId
        join lSalesTable
            where lSalesTable.RecId == nDX_MultipleS_Sales.RefRecId_SalesTable
    {
        if (!lFirst)
        {
            range2String += #Comma;
        }
        else
        {
            lFirst = false;
        }

        range2String += lSalesTable.SalesId;
    }
    return range2String;
}

public void insert()
{
    NDXMultipleS_Sales orig = this.orig();
    super();
    this.writeLog(orig, this);
}

public void update()
{
    NDXMultipleS_Sales orig = this.orig();
    super();
    this.writeLog(orig, this);
}

public void delete()
{
    NDXMultipleS_Sales orig = this.orig();
    super();
    this.writeLog(orig, null);
}

/// <summary>
/// Writes a lof for change
/// </summary>
/// <param name = "_orig">record before</param>
/// <param name = "_current">record after</param>
private void writeLog(NDXMultipleS_Sales _orig, NDXMultipleS_Sales _current)
{
    NDXMultipleS_Log   multipleS_Log;

    if(!_current)
    {
        multipleS_Log.RefRecIdInventTable = _orig.RefRecId_InventTable;
    }
    else
    {
        multipleS_Log.RefRecIdInventTable = _current.RefRecId_InventTable;
    }

    if (_orig.RefRecId_SalesTable != _current.RefRecId_SalesTable)
    {
        multipleS_Log.ValidityCheckType = NDXValidityCheckType::SalesNumber;
        multipleS_Log.RangeValue        =  SalesTable::findRecId(_current.RefRecId_SalesTable).SalesId;

        if (!_orig.RefRecId_SalesTable)            // Neuanlage
        {
            multipleS_Log.ChangeType        = NDXChangeType::New;
        }
        else if (!_current.RefRecId_SalesTable) // Löschung
        {
            multipleS_Log.RangeValue        = SalesTable::findRecId(_orig.RefRecId_SalesTable).SalesId;
            multipleS_Log.ChangeType        = NDXChangeType::Delete;
        }
        else                                // Änderung
        {
            multipleS_Log.RangeValue        += strFmt("@ApplicationFoundation:DocuDeletedRefCaptionGeneratorFromLabel", SalesTable::findRecId(_orig.RefRecId_SalesTable).SalesId);
            multipleS_Log.ChangeType        = NDXChangeType::Update;
        }
        multipleS_Log.insert();
    }

}
